import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { User, Briefcase, X, FileText, Award, ShieldCheck, ArrowLeft, CheckCircle2, Loader2, AlertCircle } from 'lucide-react';

const Register = () => {
  const [showModal, setShowModal] = useState(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false); // For the success screen
  const [error, setError] = useState(''); // To show if data is "wrong"
  
  // State to hold the form data
  const [formData, setFormData] = useState({
    name: '',
    org: '',
    email: ''
  });

  const navigate = useNavigate();
  const bgImage = "https://i.pinimg.com/1200x/3d/da/0d/3dda0d2769ba87e3b59597ba56f6548e.jpg";

  // Updates state when user types
  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    if (error) setError(''); 
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsVerifying(true);
    setError('');

    // --- VERIFICATION LOGIC ---
    setTimeout(() => {
      // Simple Check: Ensure name is long enough and email has an '@'
      const isValid = formData.name.length > 2 && formData.email.includes('@');

      if (isValid) {
        setIsVerifying(false);
        setIsSuccess(true); // Show the "Success" UI
        
        // Wait 2 seconds so the user can see the success message, then go to Admin
        setTimeout(() => {
          navigate('/admin');
        }, 2000);
      } else {
        setIsVerifying(false);
        setError("Verification Failed: Please check your credentials and try again.");
      }
    }, 2500); // Simulated "Check" time
  };

  return (
    <div 
      className="min-h-screen flex flex-col items-center justify-center p-6 font-sans bg-cover bg-center bg-no-repeat relative overflow-hidden"
      style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.75), rgba(88, 28, 135, 0.65)), url(${bgImage})` }}
    >
      {/* Back Button */}
      <button onClick={() => navigate('/home')} className="absolute top-8 left-8 z-20 flex items-center gap-2 text-white/70 hover:text-white transition-all group font-bold tracking-widest text-xs">
        <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> BACK TO LOGIN
      </button>

      {/* Header */}
      <div className="text-center mb-12 z-10">
        <h1 className="text-6xl font-black text-white mb-4 tracking-tighter">Start Your <span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-blue-400">Journey</span></h1>
        <p className="text-gray-300 text-lg font-medium max-w-md mx-auto">Choose your category to undergo secure verification.</p>
      </div>
      
      {/* Selection Toggle */}
      <div className="bg-white/10 backdrop-blur-2xl p-3 rounded-[3.5rem] shadow-2xl flex border border-white/10 w-full max-w-xl z-10 transition-all">
        <button onClick={() => setShowModal('student')} className="flex-1 flex flex-col items-center justify-center py-12 rounded-[3rem] hover:bg-purple-600/40 group transition-all">
          <div className="bg-purple-500/20 text-purple-400 p-5 rounded-3xl mb-4 group-hover:bg-white group-hover:text-purple-600 transition-all shadow-xl"><User size={40} /></div>
          <span className="font-black text-white text-xl tracking-tight">STUDENT</span>
        </button>
        <div className="w-[1px] bg-white/10 my-8"></div>
        <button onClick={() => setShowModal('hr')} className="flex-1 flex flex-col items-center justify-center py-12 rounded-[3rem] hover:bg-blue-600/40 group transition-all">
          <div className="bg-blue-500/20 text-blue-400 p-5 rounded-3xl mb-4 group-hover:bg-white group-hover:text-blue-600 transition-all shadow-xl"><Briefcase size={40} /></div>
          <span className="font-black text-white text-xl tracking-tight uppercase">HR / Company</span>
        </button>
      </div>

      {/* Verification Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-xl flex items-center justify-center z-50 p-4">
          
          {/* If not success yet, show form */}
          {!isSuccess ? (
            <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden animate-in zoom-in duration-300">
              <div className={`p-8 text-white flex justify-between items-center ${showModal === 'student' ? 'bg-indigo-600' : 'bg-blue-600'}`}>
                <div className="flex items-center gap-4">
                  <ShieldCheck size={32} />
                  <h2 className="text-2xl font-black uppercase tracking-tighter">Identity Check</h2>
                </div>
                <button onClick={() => setShowModal(null)} className="hover:bg-black/20 p-2 rounded-full transition-all"><X size={24} /></button>
              </div>

              <form onSubmit={handleSubmit} className="p-10 grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[70vh] overflow-y-auto custom-scrollbar">
                
                {/* Error Banner */}
                {error && (
                  <div className="col-span-2 bg-red-50 text-red-600 p-4 rounded-2xl flex items-center gap-3 border border-red-100 animate-pulse">
                    <AlertCircle size={20} />
                    <span className="text-xs font-bold uppercase">{error}</span>
                  </div>
                )}

                <input type="text" name="name" placeholder="Full Name" className="input-style" onChange={handleInputChange} required />
                <input type="text" name="org" placeholder={showModal === 'student' ? "College Name" : "Company Name"} className="input-style" onChange={handleInputChange} required />
                <input type="email" name="email" placeholder="Official Email" className="input-style" onChange={handleInputChange} required />
                <input type="text" placeholder="Designation" className="input-style" required />
                
                <div className="col-span-2 border-2 border-dashed border-gray-200 p-10 rounded-[2.5rem] text-center bg-gray-50/50 hover:bg-gray-100 transition-all">
                  <FileText className="mx-auto text-gray-400 mb-2" size={32} />
                  <p className="text-sm font-black text-gray-700 uppercase tracking-tighter">Document Upload</p>
                  <input type="file" className="mt-4 text-xs block w-full text-gray-400" required />
                </div>

                <button 
                  type="submit"
                  disabled={isVerifying}
                  className={`col-span-2 py-6 rounded-[1.5rem] font-black text-white shadow-xl transition-all flex items-center justify-center gap-3 mt-4 ${
                    isVerifying ? 'bg-amber-500 animate-pulse' : (showModal === 'student' ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-blue-600 hover:bg-blue-700')
                  }`}
                >
                  {isVerifying ? <><Loader2 className="animate-spin" /> VALIDATING DATA...</> : 'LAUNCH VERIFICATION'}
                </button>
              </form>
            </div>
          ) : (
            /* SUCCESS UI */
            <div className="text-center animate-in zoom-in duration-500">
              <div className="w-24 h-24 bg-green-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-[0_0_50px_rgba(34,197,94,0.4)]">
                <CheckCircle2 size={50} className="text-white animate-bounce" />
              </div>
              <h2 className="text-5xl font-black text-white mb-2 tracking-tighter uppercase">Verified!</h2>
              <p className="text-green-300 font-bold uppercase tracking-[0.2em] text-sm">Redirecting to Dashboard...</p>
            </div>
          )}
        </div>
      )}

      <style>{`
        .input-style { width: 100%; padding: 1.15rem 1.5rem; background-color: #f8fafc; border: 2px solid #f1f5f9; border-radius: 1.25rem; outline: none; transition: all 0.3s ease; font-weight: 600; font-size: 0.9rem; color: #1e293b; }
        .input-style:focus { border-color: #6366f1; box-shadow: 0 10px 25px -5px rgba(99, 102, 241, 0.2); }
      `}</style>
    </div>
  );
};

export default Register;
